import { MODES } from '../model.ts';
import { schemeId, themeModes, type PlatformModel } from './model.ts';

/** Compose Color takes 0xAARRGGBB; CSS hex8 is #RRGGBBAA. */
export function kotlinColor(hex: string): string {
  const h = hex.slice(1).toUpperCase();
  const alpha = h.length === 8 ? h.slice(6) : 'FF';
  return `Color(0x${alpha}${h.slice(0, 6)})`;
}

export function renderKotlin(model: PlatformModel): string {
  const lines = [
    '// Generated by @gremorie/tokens (nx build tokens). Do not edit.',
    '// One Material 3 ColorScheme per Gremorie theme and mode; roles without a',
    '// semantic token are derived with Material Color Utilities from the primary.',
    'package com.gremorie.tokens',
    '',
    'import androidx.compose.material3.ColorScheme',
    'import androidx.compose.material3.darkColorScheme',
    'import androidx.compose.material3.lightColorScheme',
    'import androidx.compose.ui.graphics.Color',
    '',
    'object GremorieColorSchemes {',
  ];
  for (const theme of model.themeNames) {
    const modes = themeModes(model, theme);
    for (const mode of MODES) {
      const fn = mode === 'light' ? 'lightColorScheme' : 'darkColorScheme';
      lines.push(`    val ${schemeId(theme, mode)}: ColorScheme = ${fn}(`);
      for (const role of model.m3Roles) {
        lines.push(
          `        ${role} = ${kotlinColor(modes[mode].m3[role].hex)},`,
        );
      }
      lines.push('    )', '');
    }
  }
  lines.push(
    '    fun of(theme: String, dark: Boolean): ColorScheme = when (theme) {',
  );
  for (const theme of model.themeNames) {
    lines.push(
      `        "${theme}" -> if (dark) ${schemeId(theme, 'dark')} else ${schemeId(theme, 'light')}`,
    );
  }
  lines.push(
    '        else -> throw IllegalArgumentException("Unknown Gremorie theme: $theme")',
    '    }',
    '}',
    '',
  );
  return lines.join('\n');
}
